"""Synthetic reports generated by the actual deterministic publishing runtime."""
import json
from types import SimpleNamespace
from backend.audit_agent.audit_policy_store import TaskAuditConfigRevisionStore
from backend.audit_agent.ingestion import AuditResultStore, IngestionStore
from backend.audit_agent.job_store import JobStore
from backend.reporting.integration_source import CanonicalReportSource
from backend.reporting.runtime import R31ReportRuntime
from backend.reporting.store import ReportStore

def comment(cid, uid, risk, text=None):
    return {"comment_id": cid, "sec_uid": uid, "nickname": "同名账号",
            "content": text or cid, "audit_status": "completed", "risk_level": risk,
            "risk_type": "fixture", "create_time": 1788825600}


def publish(path, name, comments, terms, rule_version, exemptions, db=None):
    path.mkdir()
    db = db or path / "report.sqlite3"
    task = "task-" + name
    JobStore(db).create(job_id=task, platform="dy", status="completed", display_name=name,
        crawl_mode="search", max_notes=1, analyze_limit=1)
    rules = {"rules": [{"id": "r1", "condition": "condition-" + rule_version}],
             "exemptions": exemptions, "ruleset_ref": {"id": "rules-" + rule_version, "version": rule_version}}
    configs = TaskAuditConfigRevisionStore(db)
    revision = configs.create(job_id=task, audit_config={"capabilities": ["text"], "rule_snapshot": rules})
    ingest = IngestionStore(db)
    batch = path / "batch.json"
    batch.write_text(json.dumps({"task_id": task, "platform": "dy", "items": [
        {"aweme_id": "10001", "title": "同一帖子", "desc": "隔离样例", "create_time": 1788825600}]}))
    ref = ingest.ingest_batch(batch, path / "raw")[0]
    result = AuditResultStore(db).upsert_result(job_id=task, platform="dy", content_key="10001",
        content_id=ref["content_id"], audit_config_revision_id=revision["id"], result={
            "title": "同一帖子", "desc": "隔离样例", "url": "https://www.douyin.com/video/10001",
            "author": {"nickname": "发布者", "sec_uid": "publisher"},
            "decision": "review", "risk_level": "medium", "summary": "隔离样例判断",
            "comments": comments, "evidence_items": [], "video_results": []})
    ingest.mark_content_status("dy", "10001", "completed", task_id=task, audit_result_id=result["id"])

    class FixtureSource(CanonicalReportSource):
        # Simulates M3's richer frozen source metadata, not a production M3 run.
        def coverage(self, task_id):
            return {"fixture": True}

        def config(self, task_id):
            data = super().config(task_id)
            data.update(resolved_search_terms=terms, ruleset_revision={"id": "rules-" + rule_version, "version": rule_version})
            return data

    store = ReportStore(db)
    result = R31ReportRuntime(store).generate(task, source=FixtureSource(db, path / "outputs"),
        checkpoint_path=path / "checkpoints.sqlite3")
    version = store.get_version(result.report_version_id)
    snapshot = store.get_source_snapshot(result.report_version_id)
    return SimpleNamespace(name=name, task=task, db=db, store=store, configs=configs,
        version=result.report_version_id, content_hash=version["content_hash"],
        snapshot_hash=snapshot["snapshot_hash"], snapshot=snapshot, path=path)



def authenticated_clients(stack, path):
    """Exercise the real cookie/CSRF middleware with isolated local users."""
    from fastapi import FastAPI
    from fastapi.testclient import TestClient
    from backend.application_auth.api import create_auth_router
    from backend.application_auth.middleware import ApplicationAuthMiddleware
    from backend.application_auth.service import ApplicationAuthService
    from backend.application_auth.store import AuthStore
    from backend.investigation_creation.principal import RequestPrincipalProvider
    from backend.api.investigation_conversation import create_investigation_conversation_router
    auth=AuthStore(path/'login.sqlite3')
    password='synthetic local acceptance password'
    owner=auth.create_user(username='collection-owner',password=password,role='user')
    other=auth.create_user(username='collection-admin',password=password,role='admin')
    with stack['creation_store'].admission.connect() as db:
        db.execute('UPDATE task_admissions SET owner_id=? WHERE owner_id=?',(owner['id'],'principal-a'))
        db.execute('UPDATE task_admissions SET owner_id=? WHERE owner_id=?',(other['id'],'principal-b'))
    stack['conversation'].principal_resolver=auth.principal_for_user
    provider=RequestPrincipalProvider()
    app=FastAPI()
    app.add_middleware(ApplicationAuthMiddleware,store=auth,cookie_name='collection-session')
    app.include_router(create_auth_router(ApplicationAuthService(auth),principal_provider=provider,
        cookie_name='collection-session',cookie_secure=False))
    app.include_router(create_investigation_conversation_router(stack['conversation'],stack['executor'],principal_provider=provider))
    clients=[]
    for username in ['collection-owner','collection-admin']:
        client=TestClient(app)
        response=client.post('/api/auth/login',json={'username':username,'password':password})
        assert response.status_code==200,response.text
        client.headers['X-CSRF-Token']=response.json()['csrf_token']
        clients.append(client)
    sid=clients[0].post('/api/investigation-workspaces',json={}).json()['workspace_session_id']
    response=clients[0].post(f'/api/investigation-workspaces/{sid}/report-sources',json={'reports':[
        {'label':n,'report_version_id':stack['reports'][n].version} for n in ['A','B']]})
    assert response.status_code==200,response.text
    return clients[0],clients[1],sid,auth
